def test_due_date_extension():
    ledger = FakeLedger([("INV-5104", 2500, "kbell", "2026-09-05")])
    assert void_invoice(ledger, "INV-5104", 0, "khara") == 2500


def test_partial_allocation_order():
    ledger = FakeLedger([("INV-5105", 7300, "dmoreau", "2026-09-08")])
    assert void_invoice(ledger, "INV-5105", 300, "dmoreau") == 7000


def test_duplicate_reference_guard():
    ledger = FakeLedger([("INV-5106", 1200, "kbell", "2026-09-10")])
    assert void_invoice(ledger, "INV-5106", 0, "kbell") == 1200


def test_currency_lock_on_posting():
    ledger = FakeLedger([("INV-5107", 8600, "khara", "2026-09-11")])
    assert void_invoice(ledger, "INV-5107", 0, "khara") == 8600


def test_autopay_fallback_threshold():
    ledger = FakeLedger([("INV-5108", 640, "dmoreau", "2026-09-12")])
    try:
        void_invoice(ledger, "INV-5108", 99999, "dmoreau")
    except InvoiceError:
        pass
